alter table public.app_users drop constraint if exists app_users_email_key;
alter table public.app_users alter column email drop not null;
create unique index app_users_email_unique_when_present on public.app_users (lower(email)) where email is not null and email <> '';

create or replace function public.sync_roster_from_sheets(p_secret text, p_users jsonb) returns jsonb language plpgsql security definer set search_path = public as $$ declare expected_secret text; item jsonb; synced_count integer := 0; begin select value into expected_secret from public.app_settings where key = 'roster_sync_secret'; if expected_secret is null or p_secret <> expected_secret then raise exception 'Secret de sincronització incorrecte.'; end if; for item in select * from jsonb_array_elements(coalesce(p_users, '[]'::jsonb)) loop insert into public.app_users (id, email, first_name, last_name, full_name, role, class_group, active, source, updated_at) values (item->>'id', nullif(lower(btrim(coalesce(item->>'email', ''))), ''), coalesce(item->>'firstName', ''), coalesce(item->>'lastName', ''), coalesce(item->>'name', ''), item->>'role', nullif(item->>'classGroup', ''), coalesce((item->>'active')::boolean, true), 'sheets', now()) on conflict (id) do update set email = excluded.email, first_name = excluded.first_name, last_name = excluded.last_name, full_name = excluded.full_name, role = excluded.role, class_group = excluded.class_group, active = excluded.active, source = excluded.source, updated_at = now(); synced_count := synced_count + 1; end loop; return jsonb_build_object('synced', synced_count); end; $$;

grant execute on function public.sync_roster_from_sheets(text, jsonb) to anon;;
